from pathlib import Path
import re, json
root = Path(__file__).resolve().parent.parent
dest = root / 'report_human_behavioral_models_video_data.md'
text = dest.read_text(encoding='utf-8')
changes = []
def edit(prefix, body):
    global text
    found = [p for p in text.split('\n\n') if p.startswith(prefix)]
    assert len(found) == 1, (prefix, len(found))
    old = found[0]
    refs = re.search(r' \[(?:F|Q|K|E)\d', old)
    text = text.replace(old, body + (old[refs.start():] if refs else ''), 1)
    changes.append(prefix)

edit('Две последние сложные группы', '''Для ограждений чтение кода заметно меняет оценку готовности. Fence-code называет четыре наблюдения на запретной стороне `crossed`, хотя предыдущая безопасная сторона не требуется; пять позных flags могут назвать climbing человека, который тянется вверх. В двух проверенных роликах человек возвращается на ту же видимую сторону, а в wall sample экранный timecode идёт назад. Происхождение и права неизвестны; подтверждённой реальной CCTV эти записи не стали. У SynthSite яснее определены labels: 227 generated clips, 150 unanimous Tier1 и 77 disagreement Tier2. `True_Positive/False_Positive` — имена GT-классов, а не результат нашей модели. Весь набор синтетический. Code агрегирует hazard по всему клипу и оценивает масштаб по предполагаемой высоте человека 1.75 m; калибровку и непрерывность одной пары это не устанавливает.''')
edit('У hook-paper cue', '''В hook-paper наблюдаемый признак уже заявленного вывода о безопасности: близкий крюк выше harness center не показывает закрытый замок, принадлежность lanyard и допустимость анкера. Данные предоставляются по запросу; готовых весов в прочитанной статье не найдено. У SAFELIFT получены полезные реальные короткие видео и физические endpoint fields, но почти все `subjective_judgment` равны `unknown`, остальные — `intermediate`. Бинарного unsafe и фактической массы, частоты, качества хвата, маршрута в GT нет. Даже точные углы тела не заполнят эти поля. Для обеих веток нужны внешний доступ и определение процедуры; увеличение модели само по себе не закрывает пробел.''')
edit('Клип-классификатор обычно', '''Клип-классификатор обычно отвечает, какое действие описывает поданный клип. Для сервиса нужно установить, кто выполняет действие сейчас, когда появились достаточные признаки, продолжается ли событие и была ли пауза наблюдения. Названия smoking или talking on cell phone не сообщают действующее разрешение и не назначают правильную пару. Усложнение временной модели повышает цену ошибки окна, идентичности crop или сброса состояния. Поэтому сначала следует измерить ошибки detector/track/rule, а модель добавлять для конкретной нерешённой причины.''')
edit('У MoViNet-A0 Stream', '''У MoViNet-A0 Stream [float TFLite](https://storage.googleapis.com/tf_model_garden/vision/movinet/movinet_a0_stream.tflite) получен целиком: 27 141 832 B, SHA256 `04c02709bce4a8233b03f36620909924735051cfd4bcc83e3d9d7db9bbf375ad`. Реальный интерфейс — одна `serving_default`, 44 inputs/44 outputs: image FLOAT32 `[1,1,172,172,3]`+43 states → logits FLOAT32 `[1,600]`+43 states. В бинарнике нет `init_states`; словарь состояний нужно инициализировать по фактическим shapes/dtypes и связывать по signature names, не по позиции в массивах. Внешние состояния занимают 2 696 832 B без runtime, активаций и копий; это не измеренная RAM.''')
edit('Главная семантика — накопление', '''Модель накапливает feature sum/count от последнего reset. Вычисление причинное, но классифицируется весь **prefix** после сброса, а не текущее ограниченное окно или начало/конец события. Float имеет дополнительные cumulative block pools. Пропущенная физическая секунда не продвигает модель; повторная подача старого кадра увеличивает count. Входа PTS нет. Длинная нормальная предыстория может ослаблять короткий сигнал события, а его признаки могут сохраняться после завершения. Это вывод по коду и графу, ещё не измеренное поведение. Частые сбросы меняют вычисление и требуют проверки cold start. У каждого независимого stream/camera/person crop identity должны быть свои состояния; при переприсвоении track ID их нельзя переносить другому человеку.''')
edit('Официальный INT8 variant1', '''Официальный INT8 variant1 также получен: `1.tflite`, 3 276 048 B, с явным Apache2 model-instance grant. Внешние image/buffers/logits остаются FLOAT32, counters — INT32, а внутренние вычисления квантованы. При этом это **другая архитектура**: удалены squeeze/excitation и заменены activations. Тридцать block-state outputs тождественны соответствующим inputs, накопление в head сохраняется. Сравнение float с этим INT8 одновременно измеряет изменения архитектуры и precision; назвать его чистой потерей от квантования нельзя. Имена состояний различаются slash/underscore. Исторические 65% top1/4.80 ms, Pixel4 CPU/5 FPS относятся к авторским условиям modified K600 10-second clips, не к этому float, LinQ или задержке события.''')
edit('Другие конкретные варианты', '''У других моделей тоже нужно сохранить точный временной рецепт. STGCN++ joint COCO17, MMAction1.2.0, получает 100 равномерных samples по поданному действию, двух людей и ten test clips; число samples не задаёт секунды. X3D-XS использует 4 frames, при этом crop160 в builder отличается от 182 в demo — для опыта нужен один закреплённый рецепт. TSM/TSN берут 8 segments по всему клипу, TenCrop/80 images и внутриклиповые temporal shifts; для онлайн-режима нужна другая выборка и новая оценка. VideoMAE-B16×4 с 15 views — офлайн-путь переноса с существенными требованиями к данным и устройству. AVA SlowFast32×2 использует offsets−32…+30 при 30 Hz, то есть около секунды будущего. Результат можно честно выдавать после поступления этих кадров с учётом lookahead; окно только из прошлого создаёт другой benchmark.''')
edit('Опубликованные AP/accuracy', '''Опубликованные AP/accuracy исключают разные части ошибки и полезны только рядом с условиями. Строка RTMPose pipeline 73.2 AP и 26.613 ms на i7-11700 ORT использует детектор каждые пять кадров и обходится без flip. Zoo 75.8 AP/11.06 ms относятся к pose AIC+COCO с flip и другой границей измерения. Присваивать эти цифры body7 или полному сервису нельзя. ViTPose OCHuman 88.0 AP использует GT boxes; COCO 75.8 AP — detector 56 AP и flip. Высокий pose AP при окклюзиях не включает пропущенного детектором работника. В COCO keypoint summary есть all/medium/large, без AP-small: малые люди не обязательно исключены из all, но качество для дальнего работника из него не видно.''')
edit('Сначала нужно разделить исходные записи', '''Разделять нужно исходные записи до построения crops и windows. Одна физическая запись, её синхронные виды и соседние нарезки, один film/source channel, а также родственные рендеры остаются одной группой. Выбор subject/site/camera split зависит от заявления: перенос на новую камеру знакомого цеха и на незнакомую площадку проверяют разные условия. В реестре сохраняются исходный split и текущая роль записи. Уже просмотренный разработчиком source-test не возвращается в независимый lockbox — отложенный набор, который не использовали для выбора модели и порогов. Число кадров не задаёт размер независимого теста; неопределённость оценивается по группам записей и событий.''')
edit('Особо опасны URFD', '''Особого внимания требуют URFD ceiling-view, где есть только falls; MCF с восемью камерами одного actor/scenario; CMDFall pre-cut duplicates; синхронные SmartSpaces; ENIGMA ego/exo; соседние SARD cuts одного YouTube-ID; один фильм в HMDB; соседние seconds/shots AVA; NTU pose conversions/concurrent views; пересечения K400/K700/AVA-Kinetics и связанные старые fire corpora. У NearCollision доказано перекрытие двух test windows пятью кадрами, но не утечка между splits. Для MCF scenario23 index сообщает confound-only, а report — falling intervals. До проверки его нельзя выбирать как удобный positive или negative. Утверждения SARD о package/split, count/layout ENIGMA и единицы Mmodal остаются отдельными вопросами качества источника.''')
edit('Нужны два слоя разметки', '''Исходные метки сохраняются неизменными; поверх них команда создаёт операционную эталонную разметку (GT). Минимальная запись включает source hash/revision; parent/session/sync group; subject/site/camera; time_base, rawPTS, stream_start и mapping version; event ID и actor/ordered-pair IDs; literal scenario/policy version; action/state; start/end/evidence intervals; visible/occluded/unknown; allowed ROI/active permit; left/right censoring; provenance/annotators/disagreement; train/dev/lockbox role. Физическое начало, первое доступное визуальное свидетельство, подтверждение и сообщение имеют отдельные времена. Visibility определяется независимой GT, а не успешностью детектора.''')
edit('CVAT video XML', '''CVAT video XML поддерживает frame-indexed tracks и occlusion, но для PTS и policy требуется сопровождающий файл. Consensus export может не сохранить все replicas, поэтому нужно оставлять per-job opinions и adjudication. VIA3 удобен для временных сегментов действий; BSD на его код не разрешает автоматически footage. Критические границы и отрицательные интервалы размечают независимые специалисты с сохранением разногласий. Проверяются схема, ranges, clock join, coverage и censoring. Незаполненный timestamp остаётся неизвестным; переименование lying в low-motion не добавляет наблюдения движения.''')
edit('Для оценивания до просмотра', '''До просмотра predictions фиксируется взаимно однозначное сопоставление alert↔GT: должны совпасть class, actor/pair и заранее оговорённый допуск onset/overlap. Несколько тревог на одно GT получают штраф за дублирование. Одновременно нужны recall всех известных событий, включая пропущенные и ненаблюдаемые; recall наблюдаемого/допустимого поднабора с coverage; timely recall по согласованному сроку; event precision; несопоставленные тревоги на полностью просмотренные camera-hours; duplicates/GT; ошибки onset/duration/clear и задержки. Пропуск детектора остаётся в основном знаменателе. Unknown и цензурированные случаи учитываются отдельно: если запись оборвалась до конца hold, нельзя приписать ему завершённый clear/rearm.''')
edit('Нельзя увеличивать отрицательные часы', '''Реальные отрицательные часы нельзя увеличивать титрами, застывшими или зацикленными кадрами, повтором EOF и синтетикой. Нормальная экспозиция с полной разметкой, неизвестные интервалы и состояние сервиса учитываются отдельно. Ускоренное воспроизведение только прошедших кадров измеряет момент решения по исходному времени. Для задержки доставки сообщения нужен paced/live test: wall timestamps для decode/enqueue/request/result/confirmation/storage/notification, возраст очереди, drop/reconnect и фактическое место исполнения.''')
edit('Трекер тоже меняет', '''Поведение трекера меняет смысл наблюдения. В OC-SORT8462e7… `None` возвращается до продвижения часов, пустой update их продвигает; default `max_age=30` измеряется шагами update, не секундами. Сохранённый ID после пропуска может ещё не появляться в выходе. DeepSORT/StrongSORT demos способны выдавать predicted boxes; StrongSORT++ AFLink/GSI и некоторые benchmark interpolation читают будущее. ByteTrack/BoT-SORT удаляют просроченные треки после association: если нельзя восстанавливать давно умерший ID, нужна отдельная политика исходного времени. Сохранённое состояние и предсказанный bbox не являются новым измерением позы или действия. Реестр эпизодов должен жить отдельно от track ID: исчезновение детекции не завершает нарушение, а смена ID не создаёт автоматически новый инцидент.''')
edit('**Маршрут 1:', '''**Маршрут 1: детектор, трекер и временные правила камеры.** Проверяемая гипотеза: определённое наблюдаемое событие можно распознать без общей video-action модели. Примеры — нахождение в настроенном коридоре, пламя вне действующей разрешённой ROI, пересечение измеренной области движущейся техники. Входы: кадры с исходными PTS, точная class map, ROI/policy и статус измеренного трека. Выходы: событие человека или пары, свидетельства, confirmation/clear и unknown. Непрерывные session/camera/site разделяются до настройки. На одинаковых данных сравнивают bbox-only и tracking+ledger по общим событийным метрикам, проверкам разрешённости и дублям. Путь подходит событиям, которые определяются объектом, временем и областью. Его останавливают при ненаблюдаемой физической связи, провале отрицательных проверок или недопустимом host/device split. Одно зональное правило остаётся одной функцией, даже если применяется к нескольким опасностям.''')
edit('**Маршрут 2:', '''**Маршрут 2: pose и причинные временные правила или лёгкий классификатор.** Гипотеза: при достаточной видимости человека переход, поза и измеренное движение отделяют падение от намеренного укладывания лучше, чем bbox aspect. На входе — закреплённая цепочка detector→RTMPose-m/t, sourcePTS, crops, измеренные joints/scores/track quality. На выходе — отдельные состояния подозрения на падение, положения тела, наблюдаемого малого движения и неизвестности. GMD/UR с проверенными часами используются для разработки; новую оценку строят по actor/site/camera groups с ремонтом лёжа, длинным hold и восстановлением. Сначала сравнивают bbox, tracking, pose и m/t; затем, при необходимости, чистую лёгкую голову. Скелет оставляют только при полезном качестве, coverage и задержке. Подтверждение N секунд требует принятой политики и реальных N секунд пригодных наблюдений.''')
edit('**Маршрут 3:', '''**Маршрут 3: временной RGB/skeleton-модуль, каскад или ансамбль после установленной ошибки baseline.** Гипотеза: модуль, использующий только прошлое, улучшает заданные событийные метрики там, где правилам не хватает признаков действия. Конкретные варианты — MoViNet с полным учётом состояний, X3D-XS с одним закреплённым crop/sampling recipe, STGCN++ с проверенными pose channels. Вход описывает историю, частоту и идентичность crop без подсказки границ GT; score передаётся отдельной событийной политике. Lockbox фиксируют до обучения головы и порогов. На парных событиях сравнивают timely recall, FP/hour, coverage, задержку, cold start, длину prefix и reset. Без подходящих head/labels, измеримого выигрыша и точного пути исполнения на устройстве усложнение не оправдано. Тяжёлые VideoMAE/AVA SlowFast и ансамбли остаются вне критического пути; клип с будущими кадрами не становится причинным baseline при переименовании.''')
edit('Во всех трёх маршрутах', '''Во всех трёх маршрутах decode/tracker/geometry/rules на CPU и neural graph на LinQ — пока условная архитектура. Организаторы ещё не подтвердили допустимую границу; выданных версии SDK/compiler/runtime, количества и конфигурации TPU нет. CPU без обычного GPU известен из устного пересказа команды. ONNX opset11, TFLite и отсутствие custom ops не доказывают поддержку: dynamic NMS детектора, MatMul pose и 43 stream states требуют отдельных проверок. RTX4070 из общего контекста и план аренды 1–2 RTX3090 24GB — разные ресурсные сведения. Они не подтверждают установленную среду и не разрешают аренду.''')
edit('Первым я бы проверял', '''Первый кандидат — **наблюдаемое падение** с отдельными lying/low-motion состояниями. Цепочка лучше подготовлена к инженерной проверке: точные pose bytes/prepost, исходные видео, проверенное время и намеренное укладывание/диван/кровать в качестве контрпримеров. Она позволяет быстро обнаружить ошибку обработки и проверить наличие сигнала в целевой камере. Условия допуска — определённый detector export/reference, достаточное число пикселей суставов, разрешённые непрерывные целевые positives/negatives и независимая GT. Без длинных записей обещание длительного low-motion преждевременно; диагностика сознания не входит в наблюдаемую цель.''')
edit('Вторым —', '''Второй кандидат — **один определённый сценарий бега или резкого движения у техники в конкретной камере**. Есть настоящие CCTV labels, явный actor, walking control, отдельные run/walk weights и оценка чувствительности наблюдения к низкому FPS. До допуска нужно выбрать цель — походка, смещение или физическая скорость; проверить видимость и неоднозначность часов; получить целевые быструю ходьбу, краткий рывок и зональные controls. Если проверки не пройдены, сценарий остаётся резервом. Расширение названия до любого «аномального движения» пробел не закрывает.''')
edit('Третьим, как альтернативу,', '''Условная третья альтернатива — **видимое пламя вне действующей разрешённой ROI**. Есть точный небольшой checkpoint, карта классов и AGPL; понятен путь правила. Временные контрольные примеры подготовлены слабее. Допуск требует реальных steam/dust/allowed-fire и набора onset/clear/rearm; mist sensors это условие не закрывают. Если набор не удаётся получить, третий сценарий снимается.''')
edit('Moving-forklift envelope', '''Область безопасности движущегося погрузчика полезна оператору и соответствует приоритетам кейса; это первый содержательный резерв после решения rights/pairGT/geometry. Телефон возвращается при различимом целевом device и подтверждённой одновременности действий. Нахождение в настроенном коридоре может быть узким запасным событием с точным названием. Во всех случаях сообщение должно содержать причину, опорный кадр/отрезок и понятный статус неизвестности. Длительное нарушение не должно засорять журнал повторными тревогами.''')
edit('До новых внешних входов', '''До получения новых внешних данных в stop-list входят: диагноз потери сознания; правильная привязь по hook bbox; физическое нахождение под грузом/столкновение по 2D overlap; универсальная unsafe carrying по pose; phone-while-walking на настольном Charades; ближайший класс K400/K600 в качестве industrial head; длительный hold из EOF/loops; использование будущего и interpolation под названием online; тяжёлое временное обучение без чистой GT и пути исполнения на устройстве. Сгенерированное видео не даёт реального lockbox и FP/hour. Этот список ограничивает обещания текущего решения; дальнейшие исследования соответствующих задач возможны.''')
edit('Единственное достаточно обоснованное', '''Единственное достаточно обоснованное **дополнительное исследовательское расширение** — видимая агрессия, направленная на человека (apparent person-directed aggression). В AVA есть fight/hit64 и push76, 478/86 validation person-second rows, обученный AVA head и proposals path. Но пример55Ihr6uVIDA at991s здесь не получен, нет controls для помощи, контакта и ремонта, нет промышленного holdout. Это зацепка после основной задачи, а не готовая дополнительная MVP-функция. Неправильная переноска уже входит в item8 кейса; второе название одной зоны не создаёт нового нарушения. Достаточной второй цепочки расширения исследование не установило.''')
edit('Синтетические clips полезны', '''Синтетические клипы полезны для проверки автомата состояний, редких сочетаний и возможной аугментации, если происхождение помечено и исходные assets допустимы. Физику падения, контакт крюка и независимую GT расстояния они не устанавливают. SynthSite227 labels — действительно доступный артефакт схемы и результатов, но не реальный safety benchmark. Генератор может убедительно нарисовать нужную связь; для физического наблюдения камерой этого недостаточно.''')
edit('Есть опубликованные причины', '''Опубликованные результаты дают основания испытывать синтетику с ограниченными ожиданиями. SURREACT one-shot Kinetics15 использует 15 real train/725 real test clips: real-only 26.2%, synthetic-only 9.4%, real+synthetic с MiniKinetics backgrounds 32.7%, с LSUN 26.3%. В SynAPT TimeSformer HMDB51 synthetic pretrain даёт 54.38 против Kinetics 59.51, а MiniSSV2 — 51.10 против 48.92, при заданных исходных инициализациях. REMAG на 11 activities с K400-pretrained models/64 frame/300 epoch показывает synthetic на 4–8 points ниже real, conventional CG выше neural rendering, mocap выше реконструированного движения. Это авторские сравнения переноса представлений; качество промышленной тревоги по ним неизвестно.''')
edit('Разумный опыт —', '''Практический опыт сравнит одинаковый real-only baseline с тем же обучением при добавлении разрешённой синтетики, на одном независимом real lockbox. Motion/source/background и родственные рендеры группируются; трудные случаи разбираются отдельно. Эффект renderer нельзя оценивать, одновременно меняя split и backbone. VideoPhy/VBench и подобные physics/consistency benchmarks не являются safety GT. Синтетическое demo допустимо показывать с явной маркировкой; метрики реальных камер считаются отдельно.''')

# The eight protocols retain inputs, actions, decision gates, failure modes,
# saved evidence and limits of a successful outcome.
edit('Ниже — **план будущих', '''Ниже — **план будущих инженерных экспериментов**. Модельные и событийные тесты ещё не выполнены; уже сделанные проверки источников, медиа и статических схем служат их входами. Требования к recall, ложным тревогам и задержкам задают кейс и команда. Универсальные проценты, VRAM и время готовности не установлены. Полные E001–E008 с основаниями находятся в [OPEN_QUESTIONS.md](OPEN_QUESTIONS.md#E001).''')
edit('**Входы:** F005 exact registry', '''**Входы:** точный реестр F005, сохранённые полные файлы и хеши, закреплённые code/config/licenses, предполагаемое использование для private evaluation/public demo/repository и фактически доступные CPU/RTX. **Действия:** выбрать один маршрут; через разрешённый доступ получить недостающие согласованные зависимости; сохранить полный manifest и notices; проверить external data, карты классов, shape/dtype и detector→crop→decode. Для RTMPose эталон — batch1/COCO17 runtime check, SDK1.2 RGB/CropResizePad/minSimCC. Карты fire/forklift фиксируются отдельно. Для MoViNet выбирается float либо modified INT8 с полным набором 43 states.''')
edit('**Наблюдение и gate:** либо воспроизводимая', '''**Критерий решения:** получена полная воспроизводимая цепочка с допустимым предполагаемым использованием и определённой pre/post либо точно назван недостающий файл/условие. Остановка — недоступный matching checkpoint, отсутствующий external tensor, недопустимое использование, неустранимая неоднозначность class/decoder. **Типичные провалы:** похожее имя принято за эквивалентный экспорт, HTML — за вес, разрешение на код — за разрешение на медиа, частичный хеш — за полный. **Сохранить:** URLs/revisions/full hashes, тип и время получения, среду, условия и открытые вопросы прав. **Успех не доказывает:** исполнение, различимость нужных пикселей, качество, скорость или LinQ.''')
edit('**Входы:** разрешённые непрерывные target recordings', '''**Входы:** разрешённые непрерывные целевые записи, source annotations/clock maps, наборы для разработки, сведения subject/site/camera/session/sync/policy. **Действия:** группировать и разделить данные до windows/crops, оставить нетронутый lockbox; проверить точные и близкие дубликаты и вложенные фрагменты; отдельно сохранить source labels и целевую схему F014. Независимо разметить существенные границы, visibility, permit, отрицательные случаи и неизвестность, сохранив individual opinions. Длинный hold и recovery получить реальной записью; отрицательную экспозицию просмотреть целиком.''')
edit('**Наблюдение и gate:** проверяемые train/dev/test', '''**Критерий решения:** проверяемые train/dev/test без утечки parent/sync, достаточная для заявленного события длительность и принятая policy. Остановка — невидимая цель, недостающие метки/права или слишком короткий хвост. **Провалы:** случайные кадры одного видео в разных splits, синхронные виды как разные события, допустимость оценки по успеху детектора, unlabeled→normal, synthetic в real lockbox. **Сохранить:** source/group/split manifest/hash, исходную и операционную разметку, часы, разногласия, цензурирование и просмотренную экспозицию. **Успех не доказывает:** качество обученной модели, причинность и представительность будущих заводов.''')
edit('**Входы:** E001 manifest', '''**Входы:** manifest E001, development-данные E002, фактические версии ПО/оборудования и sourcePTS. **Действия:** запустить точную эталонную сеть; проверить shapes/dtypes/maps, RGB/BGR, letterbox/crop и восстановление координат для обычных, краевых, обрезанных и пустых bbox. Сохранить raw outputs до postprocess; исходную модель и экспорт сравнивать только в согласованной паре. Сопоставить m/t и SDK с портированной реализацией на одинаковых tensors/boxes, сохранив детектор. У трекера проверить empty/None/gap, TTL по last measured PTS, crossing IDs/exit/re-entry/reconnect и отдельные статусы measured/predicted/retained/emitted.''')
edit('**Наблюдение и gate:** runnable reproducible', '''**Критерий решения:** запускаемый воспроизводимый эталон с правильной привязкой source/crop/actor/time. Допуск raw parity выбирается для модели/runtime; необъяснённые искажения координат, классов, цвета или состояния исправляются до целевой оценки. **Провалы:** опубликованная задержка названа измеренной, GT boxes исключают пропуски детектора, predictions приняты за observations. **Сохранить:** manifests, transforms/tensors/raw outputs/joint scores, журнал трекера, измерения времени этапов и ресурсов. **Успех не доказывает:** качество событий, допустимость host split и исполнение на устройстве.''')
edit('**Входы:** frozen reference/policy/GT', '''**Входы:** зафиксированные reference/policy/GT, заранее объявленное взаимно однозначное сопоставление, согласованный deadline и censoring. **Действия:** воспроизвести только прошлые кадры с отдельным реестром эпизодов и фиксированными hold/gap/clear/rearm; измерить все метрики F017 вместе с visibility/coverage. Проверить лежание с первого кадра, краткое событие, длинную нормальную предысторию, occlusion/unknown, восстановление, повторную готовность и reconnect. Изменить будущий suffix: прежние тревоги должны остаться неизменными. Затем paced/live test отдельно измеряет wall latency.''')
edit('**Наблюдение и gate:** match/error ledger', '''**Критерий решения:** журнал сопоставлений и ошибок показывает выполнение согласованных требований. Остановка — вход будущего или границ GT, исключение пропусков, повторные сообщения, clear-on-miss или padding-as-evidence. Если требования ещё не приняты, публикуются измерения без вердикта о приёмке; цензурированный hold остаётся неоцениваемым. **Провалы:** window accuracy подменяет event quality, выгодный допуск выбран после результата, одна тревога поглощает несколько GT, ускоренный replay назван live latency. **Сохранить:** fixed policy/matching/GT hashes, alerts/evidence/statuses, кандидатов сопоставления и решения, exposure/coverage/censoring, source/wall timestamps. **Успех не доказывает:** новую площадку, низкие FPS или LinQ.''')
edit('**Входы:** одинаковые grouped splits', '''**Входы:** одинаковые grouped splits/GT и протокол исходного времени, готовые эталонные артефакты; варианты bbox-only, bbox+tracking, pose+rules и подходящая временная голова. **Действия:** менять по одному компоненту при равных detector/input/visibility; разделить ошибки восприятия и события; сравнить m/t с общим decode. Для MoViNet проверить cold start, long prefix→event→clear, reset человека/камеры и прерывание. Modified INT8 против float сравнивать как одновременное изменение architecture+precision. Для синтетики использовать парные real-only/add-synthetic условия и real lockbox.''')
edit('**Наблюдение и gate:** paired event error', '''**Критерий решения:** парные изменения ошибок событий вместе с latency/coverage/resources показывают пользу компонента. Продвигать его только при улучшении согласованных метрик без неприемлемых новых FP/unknown/delay. Остановка — нет подходящих labels/head/rights, есть leakage/background shortcut/выигрыш только на GT boxes или новая уверенная ошибка pose. **Провалы:** разные splits/detectors, настройка на test, сравнение видео с будущим с онлайн-правилами. **Сохранить:** config/model/data hashes, paired predictions/matches, confusion/visibility strata, raw scores/state/reset, происхождение адаптации и измеренные затраты. **Успех не доказывает:** другие сценарии, камеры и перенос.''')
edit('**Входы:** frozen E004', '''**Входы:** зафиксированный E004, исходные ordinals/PTS/time_base/start, документированные аномалии CAVIAR, evaluation clock и чувствительность δ. **Действия:** причинная выборка по сеткам и фазам без изменения физических времён событий; воспроизводимые случайные и пакетные потери с seeds/masks. Раздельно отмечать source loss, queue drop, timeout, busy call и фактически пустой результат детектора. Кадры не повторять для заполнения, predictions не считать неподвижностью. Сначала подсчитать возможности наблюдения, затем измерить реальную модель, события и unknown coverage.''')
edit('**Наблюдение и gate:** phase-dependent', '''**Критерий решения:** выявлены пропуски кратких событий в зависимости от фазы, ошибки идентичности/hold и расход ресурсов. Если при данной частоте событие ненаблюдаемо, нужно менять частоту или объём заявления. **Провалы:** every12frames названо exact2FPS при25Hz, время рассчитано по новому индексу, кадры удалены по одному PTS, вход 30frame всегда считается секундой. **Сохранить:** выбранные исходные frame/PTS, phase/mapping/mask/seed, request/drop ledger, predictions/matches и кривые latency/coverage. **Успех не доказывает:** восстановленное время съёмки, другой характер потерь или пропускную способность LinQ; арифметические возможности не равны распознаванию.''')
edit('**Входы:** обследованная целевая камера', '''**Входы:** обследованная целевая камера, нужные ground/elevated/work planes/footprints, независимое состояние движения/груза, ROI/active permit/maintenance policy. **Действия:** при фиксированных perception/event rule независимо варьировать неопределённость геометрии и policy. Проверить groundcontact против bboxcenter, stationary-near/moving-far, driver-only, turn/reverse/barrier/occluded feet, перемещение камеры. Для flame — одно визуальное условие с активным и неактивным permit, для corridor — разрешённое обслуживание. Если attachment/under-load/depth не видны с одного ракурса, нужен новый сигнал или более узкое название события.''')
edit('**Наблюдение и gate:** различить perception', '''**Критерий решения:** ошибки восприятия, калибровки, границы и policy различены. Заявление о physical distance/underload/height допустимо при независимой подходящей truth; иначе остаётся предупреждение в изображении или остановка пути. **Провалы:** пиксели названы метрами, calibrationJSON — обследованием безопасности, лежащий груз — подвешенным, близкий крюк — закрытым, все люди рядом с truck — водителями. **Сохранить:** версии survey/calibration/policy и свидетельства ошибок, ROI/planes/transforms/change log, независимую control GT, uncertain-boundary/pair outputs и журнал ошибок. **Успех не доказывает:** геометрию вне плоскости, невидимое соединение, диагноз и другие камеры.''')
edit('**Входы:** выданные SDK/compiler/runtime/device', '''**Входы:** выданные SDK/compiler/runtime/device, разрешённый split, точные graph/prepost, raw reference, нетронутые целевые данные и фиксированная policy. **Действия:** экспортировать и скомпилировать официальным инструментом определённой версии; команды изобретать нельзя. Сохранить unsupported diagnostics и отдельные препятствия detector/pose/state. Подтвердить место исполнения через происхождение artifact/input/job/raw-output/runtime/device. Сопоставить raw outputs с соответствующим эталоном, затем выполнить причинную оценку событий при фиксированных decoder/threshold/policy. Любое изменение precision/shapes/prepost назвать явно. Измерить decode/queue/inference/postprocess/event/notification, drops/wall latency/state reset/reconnect.''')
edit('**Наблюдение и gate:** фактический device run', '''**Критерий решения:** фактический запуск на устройстве и приемлемые по принятым требованиям численные/событийные изменения либо точно названное препятствие. Успешная компиляция, принятый request, видимая VM и скрытый CPU fallback не означают PASS. Если путь не поддерживается, меньшая или другая эталонная модель заново проходит E001/E003/E004. **Провалы:** неверные revision/class order, preprocess mismatch объяснён «квантованием», window/queue/confirmation исключены из latency, утечка состояния при reset. **Сохранить:** хеши артефактов, версии SDK/runtime/device, compile/run logs, precision/shape/state manifests, input/job/output provenance, raw parity и журнал событий/времени с фиксированной policy. **Успех не доказывает:** безопасность всех заводов, поддержку всех моделей и другой LinQ configuration.''')

edit('Начать нужно с двух параллельных', '''В первые часы нужно закрывать две зависимости одновременно: фактический контракт SDK/device/host-boundary и одно определённое наблюдаемое событие с разрешённой непрерывной целевой записью. Допустимость CPU tracker/rules и поддержку выбранного graph выясняют до обучения. Одновременно фиксируют источник/split/policy, назначают нетронутый lockbox и сохраняют происхождение sourcePTS. Затем собирают один точный detector→pose или flame reference, проверяют обработку на краевых входах и переходят к причинным событийным метрикам.''')
edit('Для команды из пяти человек', '''Для пяти участников можно предложить такое разделение: первый ведёт точные model/runtime/export и доказательства LinQ; второй — source/media/clock/annotation/split; третий — причинный tracker и журналы событий/сообщений; четвёртый — измерения, контрольные примеры и разбор ошибок; пятый — policy, сценарий оператора, воспроизводимое demo и соответствие презентации фактам. Это предложение, а не уже назначенные роли. Неправильную class map или недостающую наблюдаемую связь нужно передавать коллегам сразу: такая находка может изменить решение раньше очередного обучения. Все работают с одной закреплённой версией данных, модели и политики.''')

# Exact line replacements keep the five questions parallel and readable.
questions = {
'1. Какой exact LinQ': '1. Какие именно LinQ device/SDK/compiler/runtime и API выданы? Какое доказательство реального исполнения принимается и какие decode/tracker/geometry/rules разрешено оставить на CPU?',
'2. Как определяются выбранные': '2. Как определяются выбранные события и допустимые miss/false-alert/duplicate/latency budgets? «Несколько секунд» отсчитывают от physical onset, first visible evidence или confirmation? Какие hold/gap/clear/rearm правила принимаются?',
'3. Какие permissioned continuous': '3. Какие разрешённые непрерывные целевые видео, сведения о камере/контексте/калибровке и независимые actor/pair/visibility labels доступны? Есть ли длинные normal/confuser/hold/recovery интервалы и нетронутый test?',
'4. Какие camera-specific ROI': '4. Какие ROI конкретной камеры, active permit, сведения о machine/driver, высотной работе/креплении и процедуры обращения с грузом определяют нарушение? Какие условия нельзя установить одной камерой?',
'5. Что разрешено показывать': '5. Что из целевого и исходного footage разрешено показывать и распространять в публичном demo/репозитории? Какое расписание действует при расхождении третьего checkpoint: 24 октября 18:00 в историческом контексте и 19:00 в оригинале кейса?'
}
lines = text.splitlines()
for prefix, new in questions.items():
    indices = [i for i, line in enumerate(lines) if line.startswith(prefix)]
    assert len(indices) == 1, prefix
    lines[indices[0]] = new
text = '\n'.join(lines) + '\n'
edit('Последнее расхождение нельзя', '''До уточнения расписания расхождение нельзя трактовать как свободный выбор срока. Локально прочитанный кейс даёт финальную загрузку 25 октября до 10:00 МСК. Текущий личный кабинет исследование не проверяло.''')
edit('У команды теперь есть', '''Для следующего шага есть конкретные файлы и проверенные ограничения их применения. Решающее новое доказательство — воспроизводимый причинный эталон на разрешённом целевом видео с независимой GT, полным жизненным циклом события и последующим точным запуском на LinQ. Качество новой камеры, фактическая скорость и допустимая аппаратная граница до этого остаются открытыми.''')

dest.write_text(text, encoding='utf-8', newline='\n')
(root / '_WORK/EDITOR_CHANGES_FINISH.json').write_text(json.dumps(changes, ensure_ascii=False, indent=2), encoding='utf-8')
print(f'Edited {len(changes)} more passages; {len(text.encode("utf-8"))} bytes')
